import { useState, useEffect, useCallback } from "react";
import { hodReviewService } from "../services/EvaluationApiService";
import { ReviewScorecardJob, ReviewScorecardCandidate } from "../services/IEvaluationService";

export interface UseReviewScorecardResult {
  jobs: ReviewScorecardJob[];
  jobsLoading: boolean;
  drawerOpen: boolean;
  selectedJob: ReviewScorecardJob | null;
  candidates: ReviewScorecardCandidate[];
  candidatesLoading: boolean;
  selectedCandidate: ReviewScorecardCandidate | null;
  modalOpen: boolean;
  alertMsg: string;
  alertType: "success" | "error" | "";
  openDrawer: (job: ReviewScorecardJob) => Promise<void>;
  closeDrawer: () => void;
  openCandidateModal: (candidate: ReviewScorecardCandidate) => void;
  closeCandidateModal: () => void;
  setAlert: (message: string, type: "success" | "error") => void;
  submitHodDecision: (payload: any) => Promise<{ success: boolean; message?: string }>;
}

export function useReviewScorecard(
  roleIDs: number[],
  employeeList: any[],
  hodEmail: string,
  onFormOpen?: (open: boolean) => void
): UseReviewScorecardResult {
  const [jobs, setJobs] = useState<ReviewScorecardJob[]>([]);
  const [jobsLoading, setJobsLoading] = useState<boolean>(true);
  const [drawerOpen, setDrawerOpen] = useState<boolean>(false);
  const [selectedJob, setSelectedJob] = useState<ReviewScorecardJob | null>(null);
  const [candidates, setCandidates] = useState<ReviewScorecardCandidate[]>([]);
  const [candidatesLoading, setCandidatesLoading] = useState<boolean>(false);
  const [selectedCandidate, setSelectedCandidate] = useState<ReviewScorecardCandidate | null>(null);
  const [modalOpen, setModalOpen] = useState<boolean>(false);
  const [alertMsg, setAlertMsg] = useState<string>("");
  const [alertType, setAlertType] = useState<"success" | "error" | "">("");

  useEffect(() => {
    if (!hodEmail || !roleIDs.length) {
      setJobs([]);
      setJobsLoading(false);
      return;
    }

    let cancelled = false;
    (async () => {
      setJobsLoading(true);
      const result = await hodReviewService.fetchReviewScorecardJobs(hodEmail);
      if (!cancelled) {
        setJobs(result);
        setJobsLoading(false);
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [hodEmail, roleIDs]);

  const openDrawer = useCallback(async (job: ReviewScorecardJob) => {
    setSelectedJob(job);
    setDrawerOpen(true);
    setCandidatesLoading(true);

    const result = await hodReviewService.fetchCandidatesForJob(job.recruitmentID, job.jobCodeID, employeeList);
    setCandidates(result);
    setCandidatesLoading(false);
  }, [employeeList]);

  const closeDrawer = useCallback(() => {
    setDrawerOpen(false);
    setSelectedJob(null);
    setCandidates([]);
  }, []);

  const openCandidateModal = useCallback((candidate: ReviewScorecardCandidate) => {
    setSelectedCandidate(candidate);
    setModalOpen(true);
    onFormOpen?.(true);
  }, [onFormOpen]);

  const closeCandidateModal = useCallback(() => {
    setModalOpen(false);
    setSelectedCandidate(null);
    onFormOpen?.(false);
  }, [onFormOpen]);

  const setAlert = useCallback((message: string, type: "success" | "error") => {
    setAlertMsg(message);
    setAlertType(type);
  }, []);

  const submitHodDecision = useCallback(async (payload: any) => {
    return await hodReviewService.submitHodDecision(payload);
  }, []);

  return {
    jobs,
    jobsLoading,
    drawerOpen,
    selectedJob,
    candidates,
    candidatesLoading,
    selectedCandidate,
    modalOpen,
    alertMsg,
    alertType,
    openDrawer,
    closeDrawer,
    openCandidateModal,
    closeCandidateModal,
    setAlert,
    submitHodDecision,
  };
}
